def login(self, username, password):
    response = self.send_request({'user': username, 'password': password}, path='/my/login/path')
    try:
        self.connection._auth = {'X-api-token': response['token']}
    except KeyError:
        raise AnsibleAuthenticationFailure(message="Failed to acquire login token.")

def logout(self):
    self.send_request(None, path='/my/logout/path')
    self.connection._auth = None
```
`logout()` runs automatically when the connection closes or resets.
